param(
  [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $Root ".orcaly-backups\documento-e-mp-unico-$Stamp"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

function Full([string]$Path) {
  Join-Path $Root ($Path -replace "/", "\")
}

function Backup-File([string]$Path) {
  $Source = Full $Path

  if (-not (Test-Path -LiteralPath $Source)) {
    return
  }

  $Destination = Join-Path $Backup ($Path -replace "/", "\")
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orcaly."
}

$Branch = (& git branch --show-current 2>$null | Out-String).Trim()

if ($Branch -ne "feature/asaas-sandbox") {
  throw "Branch atual: $Branch. Execute na branch feature/asaas-sandbox."
}

$Targets = @(
  "app/cadastro/page.tsx",
  "app/api/checkout/lead/route.ts",
  "lib/signup-checkout.ts",
  "components/checkout/SignupCheckout.tsx",
  "components/checkout/CheckoutClient.tsx",
  "components/painel/MarketplacePaymentsPanel.tsx",
  "lib/panel-modules.ts",
  "app/painel/formas-pagamento/page.tsx"
)

foreach ($Target in $Targets) {
  if (-not (Test-Path -LiteralPath (Full $Target))) {
    throw "Arquivo necessario nao encontrado: $Target"
  }
}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "ORCALY - DOCUMENTO E MERCADO PAGO UNICO" -ForegroundColor Cyan
Write-Host "CPF/CNPJ no cadastro + marketplace bloqueado sem conexao" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan

foreach ($Target in $Targets) {
  Backup-File $Target
}

$RedirectText = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("aW1wb3J0IHsgcmVkaXJlY3QgfSBmcm9tICJuZXh0L25hdmlnYXRpb24iOwoKZXhwb3J0IGRlZmF1bHQgZnVuY3Rpb24gRm9ybWFzUGFnYW1lbnRvUmVkaXJlY3RQYWdlKCkgewogIHJlZGlyZWN0KCIvcGFpbmVsL3BhZ2FtZW50b3M/dGFiPW1lcmNhZG8tcGFnbyIpOwp9Cg==")
)
[IO.File]::WriteAllText(
  (Full "app/painel/formas-pagamento/page.tsx"),
  $RedirectText.TrimEnd() + "`n",
  $Utf8
)
Write-Host "[OK] rota antiga redireciona para Mercado Pago" -ForegroundColor Green

$PatcherPath = Join-Path $Root ".orcaly-patch-documento-mp-$Stamp.cjs"
$PatcherCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)
[IO.File]::WriteAllText($PatcherPath, $PatcherCode, $Utf8)

try {
  Write-Host ""
  Write-Host "==> Aplicando regras do cadastro e marketplace" -ForegroundColor Cyan

  & node $PatcherPath

  if ($LASTEXITCODE -ne 0) {
    throw "O patcher nao conseguiu concluir as alteracoes."
  }
} finally {
  Remove-Item -LiteralPath $PatcherPath -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "==> Verificando referencias removidas" -ForegroundColor Cyan

$Legacy = @()

$Legacy += Select-String `
  -Path (Full "components/painel/MarketplacePaymentsPanel.tsx") `
  -Pattern "PaymentMethodsManager|tab=formas|activeTab === 'formas'|Pagamentos presenciais" `
  -ErrorAction SilentlyContinue

$Legacy += Select-String `
  -Path (Full "lib/panel-modules.ts") `
  -Pattern "id: 'formas_pagamento'|tab=formas" `
  -ErrorAction SilentlyContinue

if ($Legacy.Count -gt 0) {
  $Legacy | ForEach-Object {
    Write-Host "$($_.Path):$($_.LineNumber) $($_.Line.Trim())" -ForegroundColor Red
  }

  throw "Ainda existem referencias ativas a Formas de pagamento."
}

Write-Host "[OK] Formas de pagamento removido da interface" -ForegroundColor Green

if (-not $SkipBuild) {
  Write-Host ""
  Write-Host "==> Limpando cache do Next" -ForegroundColor Cyan
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build" -ForegroundColor Cyan

  & npm.cmd run build
  $BuildCode = $LASTEXITCODE

  Write-Host "BUILD_EXIT_CODE=$BuildCode"

  if ($BuildCode -ne 0) {
    Write-Host ""
    Write-Host "O build falhou. Nenhum commit foi criado." -ForegroundColor Red
    Write-Host "Backup: $Backup" -ForegroundColor Yellow
    exit $BuildCode
  }
}

Write-Host ""
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "REGRAS ATUALIZADAS" -ForegroundColor Magenta
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "Cadastro: CPF/CNPJ obrigatorio junto de nome e e-mail"
Write-Host "Checkout do cadastro: documento preenchido no Payment Brick"
Write-Host "Pix: usa o documento salvo no cadastro"
Write-Host "Painel: Formas de pagamento removido"
Write-Host "Marketplace: Mercado Pago e o unico recebimento online"
Write-Host "Sem conexao Mercado Pago: checkout e venda ficam bloqueados"
Write-Host "Com conexao Mercado Pago: Pix e cartoes sao liberados automaticamente"
Write-Host "Backup: $Backup"
